body.script:
//

/* ===== APPOINTMENT MEMORY STORE ===== */
/* Stores last appointment per phone number */
var apptStore = {};

function saveApptToStore(data){
  /* data: {phone, name, age, gender, addr, schedule, token, date} */
  if(data.phone){
    var key = data.phone.replace(/[^0-9]/g,'');
    apptStore[key] = data;
  }
}

function lookupAppt(phone){
  var key = phone.replace(/[^0-9]/g,'');
  var badge = document.getElementById('apptFoundBadge');
  if(key.length < 10){ if(badge) badge.style.display='none'; return; }
  var data = apptStore[key];
  if(!data){ if(badge) badge.style.display='none'; return; }
  /* auto-fill billing fields */
  var setV = function(id, val){ var el=document.getElementById(id); if(el && val) el.value=val; };
  setV('cName',   data.name);
  setV('cAge',    data.age);
  setV('cAddr',   data.addr);
  /* update billing address display */
  var billVal = document.getElementById('billAddrVal');
  if(billVal && data.addr){ billVal.style.color='#1a5c3a'; billVal.textContent=data.addr; }
  var gen = document.getElementById('cGender');
  if(gen && data.gender){
    /* map appt gender values to billing gender values */
    var gmap = {'পুরুষ (Male)':'Male (M)', 'মহিলা (Female)':'Female (F)', 'অন্যান্য (Other)':'Other'};
    gen.value = gmap[data.gender] || '';
  }
  if(badge) badge.style.display='inline-block';
}

/* ---- Tab Switching ---- */
function switchTab(tab){
  var tabs = ['diag','appt','bill'];
  tabs.forEach(function(t){
    var btn = document.getElementById('tab-'+t);
    var pnl = document.getElementById('panel-'+t);
    if(t === tab){
      btn.classList.add('active');
      pnl.classList.add('active');
    } else {
      btn.classList.remove('active');
      pnl.classList.remove('active');
    }
  });
}

/* ---- today as default date ---- */
(function(){
  var t=new Date();
  var d=t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0');
  document.getElementById('issueDate').value=d;
  document.getElementById('paidDate').value=d;
})();

var rowCount=0;

/* ===== SERVICE MENU DATA ===== */
var serviceMenu = {
  'Ruqyah': [
    {name:'Ruqyah Consultation & Diagnosis', rate:2500},
    {name:'Ruqyah Treatment – Short Session', rate:2000},
    {name:'Ruqyah Treatment – Long Session', rate:6000},
    {name:'Ruqyah Short Package', rate:15000},
    {name:'Ruqyah Full Package', rate:25000},
    {name:'Ruqyah Home Service (Same District)', rate:12000},
    {name:'Ruqyah Home Service (Other District)', rate:15000}
  ],
  'Hijamah': [
    {name:'Hijamah Back Detox', rate:2500},
    {name:'Hijamah Healing', rate:3500},
    {name:'Hijamah Healing Pro', rate:5000}
  ]
};

function addRow(){
  rowCount++;
  var tb=document.getElementById('itemsBody');
  var tr=document.createElement('tr');
  tr.id='row'+rowCount;
  var rc=rowCount;

  /* একটাই dropdown — সব সার্ভিস গ্রুপ করে */
  var allOpts = '<option value="">-- সার্ভিস সিলেক্ট করুন --</option>';
  Object.keys(serviceMenu).forEach(function(cat){
    allOpts += '<optgroup label="'+cat+'">';
    serviceMenu[cat].forEach(function(s,i){
      allOpts += '<option value="'+cat+'|'+i+'">'+s.name+' (৳'+s.rate+')</option>';
    });
    allOpts += '</optgroup>';
  });

  tr.innerHTML=
    '<td style="font-size:11px;color:#888;">'+rc+'</td>'
   +'<td style="padding:4px 4px;">'
      +'<select id="itemSel'+rc+'" onchange="onItemChange('+rc+')" style="width:100%;border:1px solid #e0e0e0;border-radius:4px;padding:4px 4px;font-size:12px;background:#fafafa;font-family:Arial,sans-serif;outline:none;">'+allOpts+'</select>'
   +'</td>'
   +'<td><select id="typeSel'+rc+'" onchange="calcTotals()" style="width:100%;border:1px solid #e0e0e0;border-radius:4px;padding:4px 2px;font-size:11px;background:#fafafa;font-family:Arial,sans-serif;outline:none;"><option>Service</option><option>Product</option><option>Medicine</option><option>Other</option></select></td>'
   +'<td><input id="qtySel'+rc+'" type="number" value="1" min="1" oninput="calcTotals()" style="width:100%;"/></td>'
   +'<td><input id="rateSel'+rc+'" type="number" value="0" min="0" oninput="calcTotals()" style="width:100%;"/></td>'
   +'<td class="amt"><input class="tot-val auto" readonly="readonly" type="text" value="0" style="width:100%;border:none;background:#f0faf2;color:#1a5c3a;font-weight:700;"/></td>'
   +'<td><button class="del-btn" onclick="delRow('+rc+')" type="button">&#x2715;</button></td>';
  tb.appendChild(tr);
  calcTotals();
}

function onItemChange(rc){
  var val = document.getElementById('itemSel'+rc).value;
  if(!val){ document.getElementById('rateSel'+rc).value=0; calcTotals(); return; }
  var parts = val.split('|');
  var cat = parts[0], idx = parseInt(parts[1]);
  var item = (serviceMenu[cat]||[])[idx];
  if(item) document.getElementById('rateSel'+rc).value = item.rate;
  calcTotals();
}

function delRow(id){
  var r=document.getElementById('row'+id);
  if(r){r.remove();calcTotals();}
}

function calcTotals(){
  var rows=document.getElementById('itemsBody').querySelectorAll('tr');
  var sub=0;
  rows.forEach(function(tr){
    var inputs=tr.querySelectorAll('input[type=number]');
    if(inputs.length>=2){
      var qty=parseFloat(inputs[0].value)||0;
      var rate=parseFloat(inputs[1].value)||0;
      var amt=qty*rate;
      sub+=amt;
      var amtInput=tr.querySelector('td.amt input');
      if(amtInput)amtInput.value=amt.toFixed(0)+'=';
    }
  });
  document.getElementById('subTotal').value=sub.toFixed(0)+'=';
  document.getElementById('totalAmt').value=sub.toFixed(0)+'=';
  var disc=parseFloat(document.getElementById('discount').value)||0;
  var pay=sub-disc;
  if(pay<0)pay=0;
  document.getElementById('payable').value=pay.toFixed(0)+'=';
  var paidEl = document.getElementById('paidAmt');
  if(paidEl) paidEl.value = pay.toFixed(0);
}

function fmt(d){
  if(!d)return '';
  var p=d.split('-');
  return p[2]+'.'+p[1]+'.'+p[0].slice(2);
}

function sendInvoice(){
  var biz  = document.getElementById('bizName').value.trim();
  var bizA = document.getElementById('bizAddr').value.trim();
  var iDate= fmt(document.getElementById('issueDate').value);
  var cN   = document.getElementById('cName').value.trim();
  var cPh  = document.getElementById('cPhone').value.trim();
  var cAge = document.getElementById('cAge').value.trim();
  var cGen = document.getElementById('cGender').value;
  var cAd  = document.getElementById('cAddr').value.trim();
  var disc = parseFloat(document.getElementById('discount').value)||0;
  var subTotRaw = parseFloat((document.getElementById('subTotal').value||'0').replace(/[^0-9.]/g,''))||0;
  var totalARaw = subTotRaw;
  var payRaw    = totalARaw - disc; if(payRaw<0)payRaw=0;
  var pAmt = document.getElementById('paidAmt').value||'0';
  var pTxn = document.getElementById('paidTxn').value.trim()||'Cash';
  var pDt  = fmt(document.getElementById('paidDate').value);

  if(!cN){ alert('রোগীর নাম দিন'); document.getElementById('cName').focus(); return; }
  if(!cPh){ alert('রোগীর ফোন নম্বর দিন'); document.getElementById('cPhone').focus(); return; }

  var rows = document.getElementById('itemsBody').querySelectorAll('tr');
  if(rows.length===0){ alert('অন্তত একটি আইটেম যোগ করুন'); return; }

  /* ── build message ── */
  var B = '────────────────────';
  function box(content){ return '┌'+B+'\n│ '+content+'\n└'+B+'\n'; }
  var m = '';

  /* ── HEADER ── */
  m += '🧾 *Billing Invoice*\n';
  if(biz)  m += box('🏢 *'+ biz +'*');
  if(bizA) m += box('📍 '+ bizA);
  m += box('📅 Issue date: *'+ iDate +'*');
  m += '\n';

  /* ── BILL TO ── */
  m += '👤 *Bill to*\n';
  m += box('নাম      : '+ cN);
  /* বয়স ও লিঙ্গ একই বক্সে */
  if(cAge && cGen) m += box('বয়স : '+ cAge +'  |  লিঙ্গ : '+ cGen);
  else if(cAge)    m += box('বয়স      : '+ cAge);
  else if(cGen)    m += box('লিঙ্গ     : '+ cGen);
  if(cAd)  m += box('ঠিকানা   : '+ cAd);
  m += box('Phone    : '+ cPh);
  m += '\n';

  /* ── ITEMS ── */
  m += '📋 *Bill Items*\n';
  var idx = 1;
  rows.forEach(function(tr){
    var selects = tr.querySelectorAll('select');
    var inputs  = tr.querySelectorAll('input[type=number]');
    var cat      = selects[0] ? selects[0].value : '';
    var itemSel  = selects[1];
    var itemName = '';
    if(cat && itemSel && itemSel.value !== ''){
      var svcIdx = parseInt(itemSel.value);
      var svc = (serviceMenu[cat]||[])[svcIdx];
      itemName = svc ? svc.name : '';
    }
    if(!itemName && cat) itemName = cat;
    var type = selects[2] ? selects[2].value : 'Service';
    var qty  = inputs[0] ? inputs[0].value : '1';
    var rate = inputs[1] ? inputs[1].value : '0';
    var amtInput = tr.querySelector('td.amt input');
    var amt = amtInput ? amtInput.value.replace(/[^0-9]/g,'') : '0';
    m += box('#'+ idx +' *'+ itemName +'* | Type: '+ type);
    m += box('Qty: '+ qty +'  |  Rate: '+ rate +'=  |  💰 '+ amt +'=');
    m += '\n';
    idx++;
  });

  /* ── TOTALS ── */
  m += '🧮 *Summary*\n';
  m += box('Sub Total : '+ subTotRaw.toFixed(0) +'=  |  Total : '+ totalARaw.toFixed(0) +'=');
  m += box('Discount  : '+ disc.toFixed(0) +'=  |  ✅ *Payable : '+ payRaw.toFixed(0) +'=*');
  m += '\n';

  /* ── PAID ── */
  m += '💳 *Paid Amount*\n';
  m += box('💳 '+ pAmt +'=  |  '+ pTxn +'  |  '+ pDt);
  m += '\n';

  m += '🙏 ধন্যবাদ! আল্লাহ শেফা দিন। আমীন।\n';
  m += '📎 বিস্তারিত Invoice PDF সংযুক্ত করা হয়েছে।';

  /* ── সেন্টারের নম্বরে পাঠাও ── */
  var centerRaw = (document.getElementById('centerPhone').value||'').replace(/[^0-9]/g,'');
  if(centerRaw.length >= 10){
    var centerNum = '88' + centerRaw.replace(/^88/,'');
    window.open('https://api.whatsapp.com/send?phone='+ centerNum +'&text='+ encodeURIComponent(m), '_blank');
  }

  /* ── পেশেন্টের নম্বরে পাঠাও ── */
  var rawPh = cPh.replace(/[^0-9]/g,'');
  if(rawPh.length >= 10){
    var waPhone = '88' + rawPh.replace(/^88/,'');
    setTimeout(function(){
      window.open('https://api.whatsapp.com/send?phone='+ waPhone +'&text='+ encodeURIComponent(m), '_blank');
    }, 800);
  }
}

/* ===== PDF DOWNLOAD ===== */
function downloadInvoicePDF(){
  var biz   = document.getElementById('bizName').value.trim() || 'Ruqyah Haven';
  var bizA  = document.getElementById('bizAddr').value.trim();
  var iDate = fmt(document.getElementById('issueDate').value);
  var cN    = document.getElementById('cName').value.trim();
  var cPh   = document.getElementById('cPhone').value.trim();
  var cAge  = document.getElementById('cAge').value.trim();
  var cGen  = document.getElementById('cGender').value;
  var cAd   = document.getElementById('cAddr').value.trim();
  var disc  = parseFloat(document.getElementById('discount').value)||0;
  var subTotRaw = parseFloat((document.getElementById('subTotal').value||'0').replace(/[^0-9.]/g,''))||0;
  var totalARaw = subTotRaw;
  var payRaw    = totalARaw - disc; if(payRaw<0)payRaw=0;
  var pAmt  = document.getElementById('paidAmt').value||'0';
  var pTxn  = document.getElementById('paidTxn').value||'Cash';
  var pDt   = fmt(document.getElementById('paidDate').value);
  var logoSrc = document.getElementById('logoImg') ? document.getElementById('logoImg').src : '';

  if(!cN){ alert('রোগীর নাম দিন'); document.getElementById('cName').focus(); return; }
  var rows = document.getElementById('itemsBody').querySelectorAll('tr');
  if(rows.length===0){ alert('অন্তত একটি আইটেম যোগ করুন'); return; }

  /* ── address & phone maps ── */
  var addrMap = {
    'Narayanganj':'House# 254/17, 1st Floor,<br>Lokman Tower,<br>Mahmudnagar Signboard,<br>Dhaka 1361.<br>Signboard, Dhaka,<br>Bangladesh, 1361',
    'Halishahr':'House# 1660, 2nd Floor,<br>Salam Avenue, P.C Road,<br>Nayabazar, Halishahr,<br>Chattogram.<br>(Opposite Halishahr Mart Supershop,<br>Abdul Khalek Sawdagar Bari)',
    "Cox's Bazar":"Cox's Bazar Sadar",
    'Jashore':'Ground Floor, House# A-17,<br>New Market (Inside the lane<br>adjacent to Hanif Bus Counter,<br>Opposite side of Steadfast<br>Courier Service Hub),<br>Jessore Sadar, Jessore - 7400'
  };
  var phoneMap = {'Narayanganj':'01883269615','Halishahr':'01978004575',"Cox's Bazar":'01813530359','Jashore':'01577555921'};
  var centerAddr  = addrMap[bizA] || (bizA||'').replace(/\n/g,'<br>');
  var centerPhone = phoneMap[bizA]||'';

  /* ── items rows ── */
  var itemsHTML = '';
  var iIdx = 1;
  rows.forEach(function(tr){
    var itemSelEl = document.getElementById('itemSel'+iIdx);
    var itemName  = '';
    if(itemSelEl){
      var opt = itemSelEl.options[itemSelEl.selectedIndex];
      if(opt && opt.value) itemName = opt.text.replace(/\s*\(৳[0-9,]+\)/,'').trim();
    }
    if(!itemName) itemName = '-';
    var allSel = tr.querySelectorAll('select');
    var typeSel= document.getElementById('typeSel'+iIdx) || (allSel[allSel.length-1]);
    var type   = typeSel ? typeSel.value : 'Service';
    var allInp = tr.querySelectorAll('input[type=number]');
    var qty    = allInp[0] ? allInp[0].value : '1';
    var rate   = allInp[1] ? allInp[1].value : '0';
    var amtInp = tr.querySelector('td.amt input');
    var amt    = amtInp ? amtInp.value.replace(/[^0-9]/g,'') : '0';
    var bg     = (iIdx%2===0) ? '#f9f9f9' : '#ffffff';
    itemsHTML +=
      '<tr style="background:'+bg+';">'
      +'<td style="padding:7px 5px;text-align:center;border:1px solid #ccc;font-size:12px;">'+iIdx+'</td>'
      +'<td style="padding:7px 6px;border:1px solid #ccc;font-size:12px;">'+itemName+'</td>'
      +'<td style="padding:7px 5px;text-align:center;border:1px solid #ccc;font-size:12px;">'+type+'</td>'
      +'<td style="padding:7px 5px;text-align:center;border:1px solid #ccc;font-size:12px;">'+qty+'</td>'
      +'<td style="padding:7px 5px;text-align:right;border:1px solid #ccc;font-size:12px;">'+rate+'/=</td>'
      +'<td style="padding:7px 8px;text-align:right;border:1px solid #ccc;font-size:12px;font-weight:700;">'+amt+'/=</td>'
      +'</tr>';
    iIdx++;
  });

  /* ── totals table rows ── */
  function totRow(label,val,bold){
    var s = bold ? 'font-weight:700;' : '';
    return '<tr>'
      +'<td colspan="4" style="padding:5px 8px;text-align:right;border:1px solid #ccc;font-size:12px;'+s+'">'+label+'</td>'
      +'<td colspan="2" style="padding:5px 8px;text-align:right;border:1px solid #ccc;font-size:12px;'+s+'">'+val+'</td>'
      +'</tr>';
  }

  /* ── paid rows ── */
  /* ছবি অনুযায়ী: Paid amount | Transaction(উপরে)+তারিখ(নিচে) | amount */
  var paidRows = '<tr>'
    +'<td colspan="4" style="padding:7px 8px;text-align:right;border:1px solid #ccc;font-size:12px;font-weight:700;">Paid amount</td>'
    +'<td style="padding:0;border:1px solid #ccc;text-align:center;vertical-align:middle;">'
      +'<div style="font-size:10px;color:#555;padding:3px 4px 1px;">Transaction</div>'
      +'<div style="font-size:10px;font-weight:600;padding:1px 4px 3px;border-top:1px solid #ddd;">'+pDt+'</div>'
    +'</td>'
    +'<td style="padding:7px 8px;text-align:right;border:1px solid #ccc;font-size:12px;font-weight:700;">'+pAmt+'/=</td>'
    +'</tr>';

  /* ── full HTML ── */
  var html =
    '<!DOCTYPE html><html><head><meta charset="UTF-8">'
    +'<title>Billing Invoice</title>'
    +'<style>'
    +'*{box-sizing:border-box;margin:0;padding:0;}'
    +'body{font-family:Arial,sans-serif;background:#fff;}'
    +'.page{width:210mm;min-height:297mm;margin:0 auto;padding:10mm 8mm 14mm;}'
    +'.outer-border{border:2px solid #333;padding:0;}'
    +'.inv-title-bar{text-align:center;padding:8px 0 6px;border-bottom:2px solid #333;}'
    +'.inv-title-bar h2{font-size:16px;font-weight:800;letter-spacing:1px;}'
    +'.header-row{display:flex;align-items:flex-start;justify-content:space-between;padding:10px 14px 8px;border-bottom:1px solid #ccc;}'
    +'.header-left{flex:0 0 38%;font-size:10.5px;line-height:1.85;word-break:keep-all;}'
    +'.header-left strong{font-size:11.5px;display:block;margin-bottom:3px;line-height:1.6;}'
    +'.header-center{flex:0 0 18%;display:flex;justify-content:center;align-items:center;}'
    +'.header-center img{width:58px;height:58px;object-fit:contain;}'
    +'.header-right{flex:0 0 44%;text-align:right;font-size:10.5px;}'
    +'.divider-row{height:1px;background:#ccc;margin:0 14px;}'
    +'.billto-row{display:flex;padding:7px 14px;border-bottom:1px solid #ccc;font-size:12px;gap:20px;}'
    +'table{width:100%;border-collapse:collapse;}'
    +'thead th{background:#1a5c3a;color:#fff;padding:7px 5px;font-size:12px;text-align:center;border:1px solid #1a5c3a;}'
    +'thead th:nth-child(2){text-align:left;}'
    +'@media print{'
    +'  body{margin:0;}'
    +'  .page{width:210mm;padding:12mm;}'
    +'  @page{size:A4 portrait;margin:10mm;}'
    +'}'
    +'</style>'
    +'</head><body>'
    +'<div class="page"><div class="outer-border">'

    /* title bar */
    +'<div class="inv-title-bar"><h2>Billing Invoice</h2></div>'

    /* header: left info | logo | issue date */
    +'<div class="header-row">'
      +'<div class="header-left">'
        +'<strong>'+biz+':<br>Cupping &amp; Ruqyah Center<br>'+(bizA?'('+bizA+' Branch)':'')+'</strong>'
        +(centerAddr ? centerAddr+'<br>' : '')
        +(centerPhone ? 'Phone: '+centerPhone : '')
      +'</div>'
      +'<div class="header-center">'
        +(logoSrc ? '<img src="'+logoSrc+'" alt="Logo"/>' : '')
      +'</div>'
      +'<div class="header-right">'
        +'<strong>Issue date:'+iDate+'</strong>'
      +'</div>'
    +'</div>'

    /* bill to row — exactly like image */
    +'<div class="billto-row">'
      +'<span>Bill to: <strong>'+cN+'.</strong></span>'
      +(cAge ? '<span>Age:'+cAge+'.</span>' : '')
      +(cGen ? '<span>Gender:'+cGen.replace('Male (M)','M').replace('Female (F)','F')+'</span>' : '')
    +'</div>'
    +'<div class="billto-row" style="border-bottom:2px solid #333;">'
      +(cAd ? '<span>Address: '+cAd+'.</span>' : '')
      +(cPh ? '<span>Phone: '+cPh+'</span>' : '')
    +'</div>'

    /* items table */
    +'<table>'
    +'<thead><tr>'
      +'<th style="width:32px;">#</th>'
      +'<th>Bill item</th>'
      +'<th style="width:70px;">Type</th>'
      +'<th style="width:38px;">Qty</th>'
      +'<th style="width:65px;">Rate</th>'
      +'<th style="width:70px;">Amount</th>'
    +'</tr></thead>'
    +'<tbody>'
      +itemsHTML
      +totRow('Sub Total', subTotRaw.toFixed(0)+'/=', false)
      +totRow('Total amount', totalARaw.toFixed(0)+'/=', false)
      +totRow('Discount', disc.toFixed(0)+'/=', false)
      +totRow('Payable Amount', payRaw.toFixed(0)+'/=', true)
      +paidRows
    +'</tbody>'
    +'</table>'

    +'</div></div>'
    +'<script>'
    +'window.onload=function(){'
    +'  setTimeout(function(){window.print();},800);'
    +'};'
    +'<\/script>'
    +'</body></html>';

  /* Android-safe: data URI পদ্ধতিতে নতুন ট্যাবে খোলো */
  try {
    var newWin = window.open('', '_blank');
    if(newWin){
      newWin.document.open();
      newWin.document.write(html);
      newWin.document.close();
    } else {
      /* popup blocked — fallback: data URI */
      var encoded = 'data:text/html;charset=utf-8,' + encodeURIComponent(html);
      var a = document.createElement('a');
      a.href = encoded;
      a.target = '_blank';
      a.rel = 'noopener';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }
  } catch(e){
    alert('পপআপ ব্লক হয়েছে। ব্রাউজার সেটিংসে পপআপ Allow করুন।');
  }
}

/* start with one row */
addRow();

/* ===== DIAGNOSIS DATA ===== */
var diagData = {

  basic: {
    title: '🩺 বেসিক ডায়াগনোসিস',
    color: '#1a5c3a',
    items: [
