    suggested.forEach(function(s){
      var strong = s.score >= 4;
      html += '<div class="result-prob-row">';
      html += '<span class="result-prob-name">'+s.info.emoji+' '+s.info.bn+'</span>';
      html += '<span class="result-prob-badge'+(strong?'':' low')+'">'+s.score+'টি লক্ষণ</span>';
      html += '</div>';
    });
    html += '</div>';

    html += '<div class="result-section">';
    html += '<div class="result-section-title">📋 পরবর্তী করণীয়</div>';
