function getDiagColor(key){
  var colors = {bodnazar:'#5c3a1a', jadu:'#2d1a5c', jinn:'#1a3a5c', waswasa:'#4a1a5c'};
  return colors[key]||'#1a5c3a';
}

function sendResultWA(btn){
  var encoded = btn.getAttribute('data-msg');
  var m = decodeURIComponent(encoded);
  m += '\n🙏 আল্লাহ শেফা দিন। আমীন।';
  window.open('https://api.whatsapp.com/send?phone='+getWAPhone()+'&text='+encodeURIComponent(m),'_blank');
}

function showFinalCombinedResult(){
  var info = diagPatientInfo;
  var today = new Date();
