  if(header) header.style.background = '#1a5c3a';

  var html = '';

  /* Patient info box */
  html += '<div style="background:#f0faf2;border:1px solid #b2dbb9;border-radius:10px;padding:12px;margin-bottom:12px;">';
  html += '<div style="font-size:12px;font-weight:700;color:#1a5c3a;margin-bottom:8px;text-transform:uppercase;">👤 রোগীর তথ্য</div>';
  html += '<div style="font-size:13px;color:#333;line-height:1.8;">';
  html += '📌 নাম: <strong>'+info.name+'</strong><br>';
