  if(info.age) html += '🎂 বয়স: <strong>'+(info.age==='infant'?'০–২ বছর':info.age==='child'?'২–১২ বছর':info.age+' বছর')+'</strong><br>';
  html += '📝 ডায়াগনোসিস: <strong>'+(info.diagFor==='self'?'নিজের জন্য':'অন্যের জন্য')+'</strong>';
  html += '</div></div>';

  /* Combined WA message */
  var fullMsg = '📋 *সম্পূর্ণ ডায়াগনোসিস রিপোর্ট*\n';
  fullMsg += '👤 নাম: *'+info.name+'* | 📱 '+info.phone+'\n';
  if(info.age) fullMsg += '🎂 বয়স: '+(info.age==='infant'?'০–২ বছর':info.age==='child'?'২–১২ বছর':info.age+' বছর')+'\n';
  fullMsg += '📅 তারিখ: '+dateStr+'\n';
  fullMsg += '━━━━━━━━━━━━━━━━━━━━\n\n';

  var totalSymptoms = 0;

  diagStepOrder.forEach(function(type){
    var res = diagAllResults[type];
    var color = diagColors[type]||'#1a5c3a';
    var emoji = diagEmoji[type]||'🔍';
    var label = diagLabel[type]||type;
    var count = res ? res.keys.length : 0;
    totalSymptoms += count;

    html += '<div style="border-radius:10px;overflow:hidden;margin-bottom:10px;border:1px solid #e0e0e0;">';
    html += '<div style="background:'+color+';color:#fff;padding:10px 14px;display:flex;align-items:center;justify-content:space-between;">';
    html += '<span style="font-size:14px;font-weight:700;">'+emoji+' '+label+' ডায়াগনোসিস</span>';
    html += '<span style="background:rgba(255,255,255,0.25);border-radius:20px;padding:3px 10px;font-size:12px;font-weight:700;">'+count+'টি লক্ষণ</span>';
    html += '</div>';

    if(!res || res.keys.length === 0){
      html += '<div style="padding:10px 14px;font-size:13px;color:#888;background:#fff;">কোনো লক্ষণ চিহ্নিত হয়নি।</div>';
      fullMsg += emoji+' *'+label+' ডায়াগনোসিস* — কোনো লক্ষণ নেই\n\n';
    } else {
      html += '<div style="background:#fff;padding:8px 12px;">';
      fullMsg += emoji+' *'+label+' ডায়াগনোসিস* ('+count+'টি লক্ষণ):\n';
      res.keys.forEach(function(n, idx){
        var txt = getItemTextByType(type, n);
        html += '<div style="padding:5px 0;border-bottom:1px solid #f0f0f0;font-size:12px;color:#333;display:flex;gap:6px;">';
        html += '<span style="color:'+color+';font-weight:700;min-width:18px;">'+(idx+1)+'.</span>';
        html += '<span>'+txt+'</span></div>';
        fullMsg += (idx+1)+'. '+txt+'\n';
      });
      html += '</div>';
      fullMsg += '\n';
    }
    html += '</div>';
  });

  fullMsg += '━━━━━━━━━━━━━━━━━━━━\n';
  fullMsg += '🔢 মোট লক্ষণ: *'+totalSymptoms+'টি*\n';
  fullMsg += '🙏 আল্লাহ শেফা দিন। আমীন।';

  /* summary badge */
  html += '<div style="background:#1a5c3a;color:#fff;border-radius:9px;padding:10px 14px;text-align:center;margin-bottom:10px;font-size:14px;font-weight:700;">মোট চিহ্নিত লক্ষণ: '+totalSymptoms+'টি</div>';

  html += '<button class="result-wa-btn" onclick="sendResultWA(this)" data-msg="'+encodeURIComponent(fullMsg)+'"><i class="fab fa-whatsapp"></i> সম্পূর্ণ রিপোর্ট WhatsApp-এ পাঠাও</button>';
  html += '<button class="result-next-btn" onclick="downloadFullDiagPDF()" style="background:#1a5c3a;margin-top:8px;"><i class="fas fa-file-pdf"></i> সম্পূর্ণ রিপোর্ট PDF ডাউনলোড করুন</button>';
  html += '<button class="result-next-btn" onclick="closeResult();switchTab(&quot;appt&quot;)" style="background:#155e40;margin-top:8px;"><i class="fas fa-calendar-check"></i> এপয়েন্টমেন্ট নিন</button>';
  html += '<button class="result-close-btn" onclick="closeResult()">বন্ধ করুন</button>';

  body.innerHTML = html;
  document.getElementById('resultOverlay').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function getItemTextByType(type, n){
  var d = diagData[type];
  if(!d) return '';
  if(d.groups){
    var idx=0;
    for(var g=0;g<d.groups.length;g++){
      for(var i=0;i<d.groups[g].items.length;i++){
        idx++;
        if(idx===n) return d.groups[g].items[i];
      }
    }
    return '';
  }
  return d.items[n-1]||'';
}

function downloadFullDiagPDF(){
  var info = diagPatientInfo;
  var logoSrc = document.getElementById('logoImg')?document.getElementById('logoImg').src:'';
  var today = new Date();
  var dateStr = String(today.getDate()).padStart(2,'0')+'.'+String(today.getMonth()+1).padStart(2,'0')+'.'+String(today.getFullYear()).slice(2);

  var diagColors = {bodnazar:'#5c3a1a', jadu:'#2d1a5c', jinn:'#1a3a5c', waswasa:'#4a1a5c', bachcha:'#1a5c4a'};
  var diagLabel  = {bodnazar:'বদনজর', jadu:'জাদু', jinn:'জিন', waswasa:'ওয়াসওয়াসা', bachcha:'বাচ্চাদের'};

  var allRows = '';
  var totalCount = 0;

  diagStepOrder.forEach(function(type){
    var res = diagAllResults[type];
    var color = diagColors[type]||'#1a5c3a';
    var label = diagLabel[type]||type;
    var count = res ? res.keys.length : 0;
    totalCount += count;

    /* Section header row */
    allRows += '<tr>'
      +'<td colspan="2" style="background:'+color+';color:#fff;padding:7px 10px;font-size:12px;font-weight:700;">'+label+' ডায়াগনোসিস — '+count+'টি লক্ষণ</td>'
      +'</tr>';

    if(!res || res.keys.length === 0){
      allRows += '<tr><td colspan="2" style="padding:6px 10px;font-size:12px;color:#888;border:1px solid #ccc;">কোনো লক্ষণ চিহ্নিত হয়নি।</td></tr>';
    } else {
      res.keys.forEach(function(n, idx){
        var txt = getItemTextByType(type, n);
        var bg = (idx%2===0)?'#fff':'#f9f9f9';
        allRows += '<tr style="background:'+bg+';">'
          +'<td style="padding:6px 8px;border:1px solid #ccc;text-align:center;font-size:12px;width:36px;">'+(idx+1)+'</td>'
          +'<td style="padding:6px 10px;border:1px solid #ccc;font-size:12px;">'+txt+'</td>'
          +'</tr>';
      });
    }
  });

  var ageDisplay = '';
  if(info.age){
    ageDisplay = info.age==='infant'?'০–২ বছর':info.age==='child'?'২–১২ বছর':info.age+' বছর';
  }

  var html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>সম্পূর্ণ ডায়াগনোসিস রিপোর্ট</title>'
    +'<style>*{box-sizing:border-box;margin:0;padding:0;}body{font-family:Arial,sans-serif;}'
    +'.page{width:210mm;min-height:297mm;margin:0 auto;padding:10mm 8mm 14mm;}'
    +'.box{border:2px solid #333;}'
    +'.title{text-align:center;padding:8px;border-bottom:2px solid #333;font-size:16px;font-weight:800;letter-spacing:1px;}'
    +'.hrow{display:flex;align-items:center;justify-content:space-between;padding:10px 14px 8px;border-bottom:2px solid #333;}'
    +'.hl{font-size:11px;line-height:1.9;}'
    +'.hl strong{font-size:13px;display:block;margin-bottom:2px;}'
    +'.hc img{width:58px;height:58px;object-fit:contain;}'
    +'.hr{text-align:right;font-size:11px;line-height:1.8;}'
    +'table{width:100%;border-collapse:collapse;}'
    +'.footer{text-align:center;padding:10px;font-size:11px;color:#555;border-top:1px solid #ccc;}'
    +'@media print{body{margin:0;}.page{width:100%;padding:8mm;}@page{size:A4 portrait;margin:10mm;}}'
    +'</style></head><body>'
    +'<div class="page"><div class="box">'
    +'<div class="title">📋 সম্পূর্ণ ডায়াগনোসিস রিপোর্ট</div>'
    +'<div class="hrow">'
      +'<div class="hl"><strong>Ruqyah Haven — Cupping &amp; Ruqyah Center</strong>'
        +'নাম: '+( info.name||'—')+'<br>'
        +'ফোন: '+(info.phone||'—')+'<br>'
        +(ageDisplay?'বয়স: '+ageDisplay+'<br>':'')
        +(info.diagFor==='self'?'নিজের জন্য':'অন্যের জন্য')
      +'</div>'
      +'<div class="hc">'+(logoSrc?'<img src="'+logoSrc+'"/>':'')+'</div>'
      +'<div class="hr"><strong>তারিখ: '+dateStr+'</strong><br>মোট লক্ষণ: <strong>'+totalCount+'টি</strong></div>'
    +'</div>'
    +'<table><tbody>'+allRows+'</tbody></table>'
    +'<div class="footer">Ruqyah Haven | আল্লাহ শেফা দিন। আমীন।</div>'
    +'</div></div>'
    +'<script>window.onload=function(){setTimeout(function(){window.print();},800);};<\/script>'
    +'</body></html>';

  openPDFTab(html);
}

