  if(!sh) return;
  if(sh.style.display === 'block'){
    sh.style.display = 'none';
  } else {
    /* always refill with current phase items */
    if(addrPhase === 'div'){
      addrFillItems(bdData.divisions, function(div){
        addrState = {div:div, dist:''};
        addrPhase = 'dist';
        var valEl = document.getElementById('addrSingleVal');
        if(valEl){ valEl.style.color='#1a5c3a'; valEl.textContent = div + ',  \u2015 \u099c\u09c7\u09b2\u09be \u09b8\u09bf\u09b2\u09c7\u0995\u09cd\u099f \u2015'; }
        document.getElementById('apptDivision').value = div;
        document.getElementById('apptAddr').value = div;
        /* immediately fill districts and keep open */
        addrFillItems(bdData.districts[div]||[], function(dist){
          addrState.dist = dist;
          var valEl2 = document.getElementById('addrSingleVal');
          if(valEl2){ valEl2.style.color='#1a5c3a'; valEl2.textContent = div + ', ' + dist; }
          document.getElementById('apptAddr').value = div + ', ' + dist;
          var sh2 = document.getElementById('addrSingleSheet');
          if(sh2) sh2.style.display = 'none';
        }, true);
        /* keep sheet open showing districts */
        var sh2 = document.getElementById('addrSingleSheet');
        if(sh2) sh2.style.display = 'block';
      });
    }
    sh.style.display = 'block';
  }
}

function addrFillItems(items, onSelect, isDistrict){
  var sh = document.getElementById('addrSingleSheet');
  if(!sh) return;
  sh.innerHTML = '';
  /* রিসেট / ব্যাক বাটন */
  var resetRow = document.createElement('div');
  resetRow.className = 'addr-drill-item';
  resetRow.style.cssText = 'color:#e53935;font-weight:700;background:#fff5f5;border-bottom:1px solid #fdd;';
  resetRow.textContent = isDistrict ? '← বিভাগে ফিরে যাও' : '✕ বাতিল করুন';
  resetRow.addEventListener('click', function(e){
    e.stopPropagation();
    if(isDistrict){
      /* ব্যাক: আবার বিভাগ দেখাও */
      addrPhase = 'div';
      addrFillItems(bdData.divisions, function(div){
        addrState = {div:div, dist:''};
        addrPhase = 'dist';
        var valEl = document.getElementById('addrSingleVal');
        if(valEl){ valEl.style.color='#1a5c3a'; valEl.textContent = div + ', — জেলা সিলেক্ট —'; }
        document.getElementById('apptDivision').value = div;
        document.getElementById('apptAddr').value = div;
        addrFillItems(bdData.districts[div]||[], function(dist){
          addrState.dist = dist;
          var valEl2 = document.getElementById('addrSingleVal');
          if(valEl2){ valEl2.style.color='#1a5c3a'; valEl2.textContent = div + ', ' + dist; }
          document.getElementById('apptAddr').value = div + ', ' + dist;
          var sh2 = document.getElementById('addrSingleSheet');
          if(sh2) sh2.style.display='none';
        }, true);
        var sh2 = document.getElementById('addrSingleSheet');
        if(sh2) sh2.style.display='block';
      }, false);
      sh.style.display='block';
    } else {
      /* বাতিল: পুরো রিসেট */
      initDrilldown();
    }
  });
  sh.appendChild(resetRow);
  items.forEach(function(item){
    var d = document.createElement('div');
    d.className = 'addr-drill-item';
    d.textContent = item;
    d.addEventListener('click', function(e){
      e.stopPropagation();
      onSelect(item);
    });
    sh.appendChild(d);
  });
}

function initDrilldown(){
  addrPhase = 'div';
  var valEl = document.getElementById('addrSingleVal');
  if(valEl){ valEl.style.color='#bbb'; valEl.textContent='-- সিলেক্ট করুন --'; }
  var sh = document.getElementById('addrSingleSheet');
  if(sh){ sh.style.display='none'; sh.innerHTML=''; }
}

