function sendAppointment(){
  var name     = document.getElementById('apptName').value.trim();
  var phone    = document.getElementById('apptPhone').value.trim();
  var age      = document.getElementById('apptAge').value.trim();
  var gender   = document.getElementById('apptGender').value;
  var addr     = document.getElementById('apptAddr').value.trim();
  var village  = document.getElementById('apptVillage') ? document.getElementById('apptVillage').value.trim() : '';
  var schedule = document.getElementById('apptSchedule').value;
  var token    = document.getElementById('apptToken').value.trim();
  var date     = fmt(document.getElementById('apptDate').value);
  var biz      = document.getElementById('apptBizName').value.trim();
  var bizA     = document.getElementById('apptBizAddr').value.trim();
  var bizWA    = document.getElementById('apptBizWA').value.trim().replace(/[^0-9]/g,'');

  if(!name){alert('রোগীর নাম দিন');document.getElementById('apptName').focus();return;}
  if(!phone){alert('WhatsApp নম্বর দিন');document.getElementById('apptPhone').focus();return;}

  /* ---- appointment memory store ---- */
  saveApptToStore({
    phone:    phone,
    name:     name,
    age:      age,
    gender:   gender,
    addr:     addr || '',
    schedule: schedule,
    token:    token,
    date:     date
  });

  var fullAddr = addr || '';
  if(!fullAddr && village) fullAddr = village;

  var B = '────────────────────';
  function waBox(content){ return '┌'+B+'\n│ '+content+'\n└'+B+'\n'; }
  var wa = '';
  wa += '📅 *অ্যাপয়েন্টমেন্ট কনফার্মেশন*\n\n';

  /* centre info */
  if(biz || token || date || schedule){
    wa += '🏢 *প্রতিষ্ঠান তথ্য*\n';
    if(biz)      wa += waBox('প্রতিষ্ঠান  : ' + biz);
    if(bizA)     wa += waBox('ঠিকানা    : ' + bizA);
    /* সিরিয়াল ও তারিখ একই বক্সে */
    if(token)    wa += waBox('সিরিয়াল নং: ' + token + '  |  তারিখ: ' + date);
    else         wa += waBox('তারিখ     : ' + date);
    if(schedule) wa += waBox('সময়       : ' + schedule);
    wa += '\n';
  }

  /* patient info */
  wa += '👤 *রোগীর তথ্য*\n';
  wa += waBox('নাম       : ' + name);
  wa += waBox('WhatsApp  : ' + phone);
  /* বয়স ও লিঙ্গ একই বক্সে */
  if(age && gender)  wa += waBox('বয়স : ' + age + '  |  লিঙ্গ : ' + gender);
  else if(age)       wa += waBox('বয়স       : ' + age);
  else if(gender)    wa += waBox('লিঙ্গ      : ' + gender);
  if(fullAddr) wa += waBox('ঠিকানা    : ' + fullAddr);
  wa += '\n';
  wa += '🙏 আল্লাহ শেফা দিন। আমীন।';

  /* ---- সেন্টারের নম্বর নির্ধারণ ---- */
  var centerNum = bizWA.length >= 10 ? ('88' + bizWA.replace(/^88/,'')) : '8801938327130';

  /* ---- রোগীর নম্বর নির্ধারণ ---- */
  var patientRaw = phone.replace(/[^0-9]/g,'');
  var patientNum = patientRaw.length >= 10 ? ('88' + patientRaw.replace(/^88/,'')) : '';

  /* ---- সেন্টারে মেসেজ পাঠাও ---- */
  window.open('https://api.whatsapp.com/send?phone=' + centerNum + '&text=' + encodeURIComponent(wa), '_blank');

  /* ---- রোগীর নম্বরে মেসেজ পাঠাও (সামান্য দেরিতে যেন দুটো ট্যাব খোলে) ---- */
  if(patientNum){
    setTimeout(function(){
      window.open('https://api.whatsapp.com/send?phone=' + patientNum + '&text=' + encodeURIComponent(wa), '_blank');
    }, 800);
  }
}

function resetAppointment(){
  ['apptName','apptPhone','apptAge'].forEach(function(id){
    var el=document.getElementById(id);
    if(el) el.value='';
  });
  /* ব্রাঞ্চ ড্রপডাউন রিসেট */
  var brAddr=document.getElementById('apptBizAddr');
  if(brAddr) brAddr.value='';
  var brWA=document.getElementById('apptBizWA');
  if(brWA) brWA.value='';
  var gs=document.getElementById('apptGender');
  if(gs) gs.value='';
  addrState = {div:'', dist:''};
  var valDiv=document.getElementById('addrSingleVal');
  if(valDiv){ valDiv.textContent='-- সিলেক্ট করুন --'; valDiv.style.color='#bbb'; }
  var sh=document.getElementById('addrSingleSheet');
  if(sh){ sh.style.display='none'; }
  var ad=document.getElementById('apptAddr');
  if(ad) ad.value='';
  var sc=document.getElementById('apptSchedule');
  if(sc) sc.value='';
  var tk=document.getElementById('apptToken');
  if(tk) tk.value='';
  initDrilldown();
}
