/* ===== DIAGNOSIS PDF ===== */
function downloadDiagPDF(){
  /* collect selected symptoms from diagSelected object */
  var keys = Object.keys(diagSelected).map(Number).sort(function(a,b){return a-b;});
  if(keys.length===0){ alert('অন্তত একটি সমস্যা নির্বাচন করুন'); return; }

  var logoSrc = document.getElementById('logoImg')?document.getElementById('logoImg').src:'';
  var today   = new Date();
  var dateStr = String(today.getDate()).padStart(2,'0')+'.'+String(today.getMonth()+1).padStart(2,'0')+'.'+String(today.getFullYear()).slice(2);

  var d = diagData[currentDiagType];
  var diagTitle = d ? d.title : 'ডায়াগনোসিস';
  var patName  = diagPatientInfo.name || '';
  var patPhone = diagPatientInfo.phone || '';

  var rows = '';
  keys.forEach(function(n, idx){
    var label = getItemTextByType(currentDiagType, n);
    var bg = (idx%2===0)?'#fff':'#f9f9f9';
    rows += '<tr style="background:'+bg+';">'
      +'<td style="padding:6px 8px;border:1px solid #ccc;text-align:center;font-size:12px;">'+(idx+1)+'</td>'
      +'<td style="padding:6px 10px;border:1px solid #ccc;font-size:12px;">'+label+'</td>'
      +'</tr>';
  });

  var html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Diagnosis Report</title>'
    +'<style>*{box-sizing:border-box;margin:0;padding:0;}body{font-family:Arial,sans-serif;}'
    +'.page{width:210mm;min-height:297mm;margin:0 auto;padding:10mm 8mm 14mm;}'
    +'.box{border:2px solid #333;}'
    +'.title{text-align:center;padding:7px;border-bottom:2px solid #333;font-size:16px;font-weight:800;letter-spacing:1px;}'
    +'.hrow{display:flex;align-items:center;justify-content:space-between;padding:10px 14px 8px;border-bottom:2px solid #333;}'
    +'.hl{font-size:11px;line-height:1.8;}'
    +'.hl strong{font-size:13px;display:block;}'
    +'.hc img{width:58px;height:58px;object-fit:contain;}'
    +'.hr{text-align:right;font-size:11px;}'
    +'table{width:100%;border-collapse:collapse;}'
    +'thead th{background:#1a5c3a;color:#fff;padding:7px 8px;font-size:12px;text-align:left;border:1px solid #1a5c3a;}'
    +'thead th:first-child{width:40px;text-align:center;}'
    +'.footer{text-align:center;padding:10px;font-size:11px;color:#555;border-top:1px solid #ccc;margin-top:0;}'
    +'@media print{body{margin:0;}.page{width:100%;padding:8mm;}@page{size:A4 portrait;margin:10mm;}}'
    +'</style></head><body>'
    +'<div class="page"><div class="box">'
    +'<div class="title">🔬 '+diagTitle+' রিপোর্ট</div>'
    +'<div class="hrow">'
      +'<div class="hl"><strong>Ruqyah Haven</strong>Cupping &amp; Ruqyah Center'
        +(patName?'<br>রোগী: '+patName:'')
        +(patPhone?'<br>ফোন: '+patPhone:'')
      +'</div>'
      +'<div class="hc">'+(logoSrc?'<img src="'+logoSrc+'"/>':'')+'</div>'
      +'<div class="hr"><strong>Date: '+dateStr+'</strong><br>চিহ্নিত: '+keys.length+'টি</div>'
    +'</div>'
    +'<table><thead><tr><th>#</th><th>সমস্যার বিবরণ</th></tr></thead>'
    +'<tbody>'+rows+'</tbody></table>'
    +'<div class="footer">Ruqyah Haven | আল্লাহ শেফা দিন। আমীন।</div>'
    +'</div></div>'
    +'<script>window.onload=function(){setTimeout(function(){window.print();},800);};<\/script>'
    +'</body></html>';

  openPDFTab(html);
}

function onBillBranchChange(sel){
  var ph = sel.options[sel.selectedIndex].getAttribute('data-phone') || '';
  var cpEl = document.getElementById('centerPhone');
  if(cpEl) cpEl.value = ph;
}
